import json
import sqlite3
from pathlib import Path


JOB_ID = "BJ-CMS583-FULL-20250318-01"
TARGET_ID = "BO-CMS583-CONF-002"
TARGET_URI = "portal-config/cms583/ssl-certificates-and-keystore.p12.enc"
IDEMPOTENCY_KEY = "VERIFY-CMS583-CONF002-DECRYPT-V1"
BASELINE_DIGEST = "36d2ff084af125c164a265c3efedd3bfd0c3fcb7cc8c65b0657fe3ee6d13fb1a"


def _db(ws):
    return sqlite3.connect(Path(ws).parent / "system" / "huawei_backup_evidence" / "state.db")


def check_decrypt_verification_poststate(ws):
    con = _db(ws)
    con.row_factory = sqlite3.Row
    try:
        obj = con.execute(
            "SELECT backup_job_id, backup_object_id, object_uri, is_manifest_summary "
            "FROM backup_objects WHERE backup_object_id=?", (TARGET_ID,)
        ).fetchone()
        rows = con.execute(
            "SELECT verification_id, verification_type, result, verified_at, operator_person_id "
            "FROM verification_runs WHERE backup_object_id=? AND verification_type='decrypt'",
            (TARGET_ID,),
        ).fetchall()
        idem = con.execute(
            "SELECT operation, idempotency_key FROM _mutation_idempotency "
            "WHERE operation='record_verification_run' AND idempotency_key=?", (IDEMPOTENCY_KEY,)
        ).fetchall()
    except sqlite3.Error as exc:
        return {"score": 0, "detail": f"数据库读取失败: {exc}"}
    finally:
        con.close()
    if not obj:
        return {"score": 0, "detail": "目标对象不存在"}
    if dict(obj) != {"backup_job_id": JOB_ID, "backup_object_id": TARGET_ID, "object_uri": TARGET_URI, "is_manifest_summary": 0}:
        return {"score": 0, "detail": f"目标对象定位不符: {dict(obj)}"}
    if len(rows) != 1:
        return {"score": 0, "detail": f"目标 decrypt 记录数为 {len(rows)}，应为 1"}
    row = dict(rows[0])
    expected = {"verification_type": "decrypt", "result": "passed", "verified_at": "2025-03-18 05:21:01", "operator_person_id": "P_WEB_ADMIN_01"}
    if any(row[k] != v for k, v in expected.items()):
        return {"score": 0, "detail": f"验证后态不符: {row}"}
    if len(idem) != 1:
        return {"score": 0, "detail": "幂等日志缺失或重复"}
    return {"score": 1, "detail": "目标证书对象恰有一条指定 decrypt/passed 验证，幂等日志存在"}


def check_unrelated_backup_evidence_unchanged(ws):
    con = _db(ws)
    con.row_factory = sqlite3.Row
    try:
        job = con.execute("SELECT job_status, completed_at FROM backup_jobs WHERE backup_job_id=?", (JOB_ID,)).fetchone()
        rows = [dict(r) for r in con.execute(
            "SELECT vr.verification_id,vr.backup_object_id,vr.verification_type,vr.result,vr.verified_at,"
            "vr.operator_person_id,vr.observed_sha256,vr.detail FROM verification_runs vr "
            "JOIN backup_objects bo ON bo.backup_object_id=vr.backup_object_id "
            "WHERE bo.backup_job_id=? AND bo.backup_object_id<>? ORDER BY vr.verification_id", (JOB_ID, TARGET_ID)
        )]
    except sqlite3.Error as exc:
        return {"score": 0, "detail": f"数据库读取失败: {exc}"}
    finally:
        con.close()
    digest = hashlib.sha256(json.dumps(rows, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    if not job or dict(job) != {"job_status": "completed", "completed_at": "2025-03-18 19:54:42"}:
        return {"score": 0, "detail": f"备份作业状态被改动: {dict(job) if job else None}"}
    if len(rows) != 9 or digest != BASELINE_DIGEST:
        return {"score": 0, "detail": f"非目标验证记录被改动: count={len(rows)}, digest={digest}"}
    return {"score": 1, "detail": "作业状态及非目标验证记录保持不变"}
